def set_budget(state, category, amount) do
  if not (is_binary(category) and category != ""), do: raise("category must be a non-empty string")
  if not (is_number(amount) and amount >= 0), do: raise("amount must be a non-negative number")
  budgets = Map.get(state, "budgets", %{}) |> Map.put(category, round(amount * 100) / 100)
  {budgets, Map.put(state, "budgets", budgets)}
end

